module top_module(
  s_aclk,
  s_aresetn,
  s_axis_tvalid,
  s_axis_tready,
  s_axis_tdata,
  m_axis_tvalid,
  m_axis_tready,
  m_axis_tdata
);input s_aclk;
input s_aresetn;
input s_axis_tvalid;
output s_axis_tready;
input [511 : 0] s_axis_tdata;
output m_axis_tvalid;
input m_axis_tready;
output reg [511 : 0] m_axis_tdata; // Change to reg type to use in always block

reg [511:0] fifo_mem [0:1023]; // FIFO memory
reg [9:0] wr_ptr = 0; // write pointer
reg [9:0] rd_ptr = 0; // read pointer
reg [9:0] fifo_count = 0; // count of elements in FIFO

// Combinational logic to check if FIFO is full or empty
wire fifo_full = (fifo_count == 1024);
wire fifo_empty = (fifo_count == 0);

// Logic to increment/decrement FIFO pointers and count
always @(posedge s_aclk) begin
    if (s_aresetn == 0) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        fifo_count <= 0;
        m_axis_tdata <= 0; // Initialize output in reset
    end else begin
        if (s_axis_tvalid && !fifo_full) begin
            fifo_mem[wr_ptr] <= s_axis_tdata;
            wr_ptr <= (wr_ptr == 1023) ? 0 : wr_ptr + 1;
            fifo_count <= fifo_count + 1;
        end
        if (m_axis_tready && !fifo_empty) begin
            m_axis_tdata <= fifo_mem[rd_ptr];
            rd_ptr <= (rd_ptr == 1023) ? 0 : rd_ptr + 1;
            fifo_count <= fifo_count - 1;
        end
    end
end

// Logic to control the ready signals
assign s_axis_tready = !fifo_full;
assign m_axis_tvalid = !fifo_empty;

endmodule

