`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (sequential circuit)
    reg m_axis_tready;
    reg s_aclk;
    reg s_aresetn;
    reg [511:0] s_axis_tdata;
    reg s_axis_tvalid;
    wire [511:0] m_axis_tdata;
    wire m_axis_tvalid;
    wire s_axis_tready;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .m_axis_tready(m_axis_tready),
        .s_aclk(s_aclk),
        .s_aresetn(s_aresetn),
        .s_axis_tdata(s_axis_tdata),
        .s_axis_tvalid(s_axis_tvalid),
        .m_axis_tdata(m_axis_tdata),
        .m_axis_tvalid(m_axis_tvalid),
        .s_axis_tready(s_axis_tready)
    );

    // Clock generation (10ns period)
    initial begin
        s_aclk = 0;
        forever #5 s_aclk = ~s_aclk;
    end

        task reset_dut;

        begin
            s_aresetn = 0;
            s_axis_tvalid = 0;
            s_axis_tdata = 0;
            m_axis_tready = 0;
            repeat(5) @(posedge s_aclk);
            s_aresetn = 1;
            repeat(5) @(posedge s_aclk);
        end
        endtask
    task testcase001;

        begin
            $display("Running testcase001: Single Word Write/Read...");
            reset_dut();


            s_axis_tvalid = 1;
            s_axis_tdata = 512'hA5A5A5A5_5A5A5A5A_12345678_87654321;
            wait(s_axis_tready);
            @(posedge s_aclk);
            s_axis_tvalid = 0;


            m_axis_tready = 1;
            wait(m_axis_tvalid);
            @(posedge s_aclk);


            #1;



            check_outputs(512'hA5A5A5A5_5A5A5A5A_12345678_87654321, 1, 1);
            m_axis_tready = 0;
            #10;
        end
        endtask

    task testcase002;

        integer i;
        begin
            $display("Running testcase002: Fill FIFO to check Full condition...");
            reset_dut();

            s_axis_tvalid = 1;
            for (i = 0; i < 1024; i = i + 1) begin
                s_axis_tdata = i;
                wait(s_axis_tready);
                @(posedge s_aclk);
            end
            s_axis_tvalid = 0;




            #1;





            check_outputs(512'h0, 1, 0);
            #10;
        end
        endtask

    task testcase003;

        integer i;
        begin
            $display("Running testcase003: Fill and Empty FIFO...");
            reset_dut();


            s_axis_tvalid = 1;
            for (i = 0; i < 10; i = i + 1) begin
                s_axis_tdata = 512'hBEEF0000 + i;
                wait(s_axis_tready);
                @(posedge s_aclk);
            end
            s_axis_tvalid = 0;


            m_axis_tready = 1;
            for (i = 0; i < 9; i = i + 1) begin
                wait(m_axis_tvalid);
                @(posedge s_aclk);
            end

            wait(m_axis_tvalid);


            #1;



            check_outputs(512'hBEEF0000 + 9, 1, 1);

            @(posedge s_aclk);
            m_axis_tready = 0;

            #10;
        end
        endtask

    task testcase004;

        integer i;
        begin
            $display("Running testcase004: Simultaneous Read and Write...");
            reset_dut();


            s_axis_tvalid = 1;
            s_axis_tdata = 512'hCAFE0000;
            wait(s_axis_tready);
            @(posedge s_aclk);


            s_axis_tvalid = 1;
            m_axis_tready = 1;
            for (i = 1; i <= 20; i = i + 1) begin
                s_axis_tdata = 512'hCAFE0000 + i;
                wait(s_axis_tready && m_axis_tvalid);
                @(posedge s_aclk);
            end

            s_axis_tvalid = 0;


            #1;



            check_outputs(512'hCAFE0000 + 20, 1, 1);

            m_axis_tready = 0;
            #10;
        end
        endtask

    task testcase005;

        begin
            $display("Running testcase005: Reset during operation...");
            reset_dut();


            s_axis_tvalid = 1;
            s_axis_tdata = 512'hFFFFFFFF;
            repeat(5) @(posedge s_aclk);


            s_aresetn = 0;
            repeat(2) @(posedge s_aclk);




            #1;





            check_outputs(m_axis_tdata, 0, 1);

            s_aresetn = 1;
            #10;
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [511:0] expected_m_axis_tdata;
        input expected_m_axis_tvalid;
        input expected_s_axis_tready;
        begin
            if (expected_m_axis_tdata === (expected_m_axis_tdata ^ m_axis_tdata ^ expected_m_axis_tdata) &&
                expected_m_axis_tvalid === (expected_m_axis_tvalid ^ m_axis_tvalid ^ expected_m_axis_tvalid) &&
                expected_s_axis_tready === (expected_s_axis_tready ^ s_axis_tready ^ expected_s_axis_tready)) begin
                $display("PASS");
                $display("  Outputs: m_axis_tdata=%h, m_axis_tvalid=%b, s_axis_tready=%b",
                         m_axis_tdata, m_axis_tvalid, s_axis_tready);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: m_axis_tdata=%h, m_axis_tvalid=%b, s_axis_tready=%b",
                         expected_m_axis_tdata, expected_m_axis_tvalid, expected_s_axis_tready);
                $display("  Got:      m_axis_tdata=%h, m_axis_tvalid=%b, s_axis_tready=%b",
                         m_axis_tdata, m_axis_tvalid, s_axis_tready);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,m_axis_tready, s_aclk, s_aresetn, s_axis_tdata, s_axis_tvalid, m_axis_tdata, m_axis_tvalid, s_axis_tready);
    end

endmodule

