description:
Design a debounce circuit for a key input signal. The module monitors a key input (`key_in`) and uses a clock signal (`clk`) to filter out noise that may occur when the key is pressed or released. It maintains a counter that increments on each clock cycle if the state of `key_in` remains stable (i.e., unchanged from its previous value). Once the counter reaches 15 million clock cycles, indicating that the input has been stable for a minimal duration, it updates the output (`key_out`) to reflect the last stable state of `key_in`. This effectively ensures that the output only changes after a sustained period of stability, thereby eliminating false triggering from noise.
module top_module( 
    input clk, 

    input key_in,
    output reg key_out=1
);

code:
module top_module( 
    input clk, 

    input key_in,
    output reg key_out=1
);reg [32:0] counter=0;
    reg last_st=0;

    always @(posedge clk) begin
        if(counter>=32'd15_000_000) begin

            key_out<=last_st;
            counter<=0;
        end
        else if(key_in==last_st)
            counter<=counter+1;
        else
            counter<=0;
		last_st<=key_in;
    end

endmodule

