description:
Design a circuit that converts a 20-bit binary encoded number into a 16-bit wide decimal representation. The module takes a 20-bit input consisting of 5 groups of 4 bits, each representing a digit in base-10 (0-9). It calculates the equivalent decimal value by weighting each digit according to its positional value, from the highest place (10,000) to the lowest (1), and sums the results to generate the 16-bit output.
module top_module(
    input [19:0] numeros,
    output [15:0] operador
);

code:
module top_module(
    input [19:0] numeros,
    output [15:0] operador
);localparam exp4 = 10000;
    localparam exp3 = 1000;
    localparam exp2 = 100;
    localparam exp1 = 10;
    localparam exp0 = 1;

    wire [15:0] num_exp4, num_exp3, num_exp2, num_exp1, num_exp0;

    assign num_exp4 = {12'b0, numeros[19:16]} * exp4;
    assign num_exp3 = {12'b0, numeros[15:12]} * exp3;
    assign num_exp2 = {12'b0, numeros[11:8]} * exp2;
    assign num_exp1 = {12'b0, numeros[7:4]} * exp1;
    assign num_exp0 = {12'b0, numeros[3:0]} * exp0;

    assign operador = num_exp0 + num_exp1 + num_exp2 + num_exp3 + num_exp4;

endmodule

