reg [3:0] product2_value = 7;
reg [1:0] product_select;
wire [3:0] product_value;
wire match;

// Counter module
always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        counter <= 0;
    end else if (enable == 1) begin
        if (counter == 9) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end
end

// Comparator module
assign product_value = (product_select == 0) ? product1_value : product2_value;
assign match = (counter == product_value);

// Multiplexer module
