    if (product_button1 == 1) begin
        product_select <= 0;
    end else if (product_button2 == 1) begin
        product_select <= 1;
    end
end

// Motor control module
always @(match) begin
    if (match == 1) begin
        dispense <= 1;
        #10 dispense <= 0;
    end else begin
        dispense <= 0;
    end
end

endmodule

