  Rx_error=0; 
  end 
  if(init) 
  begin 
  regis[i]=Rx; 
  i<=i+1; 
  if(regis[i]&&(i<8)) 
  begin 
  j=j+1; 
  end 
  end 
  if(DoIt) 
  begin 
  k<=k+1; 
  end 
  if(i==9) 
  begin 
  if(((j%2)&&(regis[8]))||(!(j%2)&&(!regis[8]))) 
  begin 
  Rx_error=0; 
  regis0={regis[7:0]}; 
  DONE=1; 
