module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter L=0, M=1, N=2;

    always_comb begin
        case (state)
            L: next_state = in1 ? N : M;
            M: next_state = in2 ? L : N;
            N: next_state = in1 ? L : M;
        endcase
    end

    assign out = (state == M);

endmodule

