    out_reg1[6] = ~in[0] & in[1] & in[2] & ~in[3];
    out_reg1[7] = ~in[0] & in[1] & in[2] & in[3];
    out_reg1[8] = in[0] & ~in[1] & ~in[2] & ~in[3];
    out_reg1[9] = in[0] & ~in[1] & ~in[2] & in[3];
    out_reg1[10] = in[0] & ~in[1] & in[2] & ~in[3];
