);// Internal wires and registers
    wire [7:0] p, g;
    reg [7:0] c;

    // Carry-lookahead adder architecture
    assign p = a ^ b;
    assign g = a & b;
    always @ (posedge clk) begin
        if (reset) begin
            c <= 8'b00000000;
            x <= 8'b00000000;
        end else begin
            if (enable) begin
                c <= g | (p & c);
                x <= p ^ c;
            end else begin
                x <= 8'b00000000;
            end
        end
    end

endmodule

