Implement the Verilog module based on the following description.
Build an 8-bit register with synchronous active high reset signal and an enable signal. When the enable signal is high, the register holds the input data.
// (1) reset: Resets the register to 8'b00000000 when high.
// (2) enable: Enables the holding of input data when high.
// (3) data_in: The input data to be held in the register.
// (4) q: The value of the register.

module top_module(
    input clk,
    input reset,
    input enable,
    input [7:0] data_in,
    output reg [7:0] q);

code:
module top_module(
    input clk,
    input reset,
    input enable,
    input [7:0] data_in,
    output reg [7:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the register to 8'b00000000
            q <= 8'b00000000;
        end else if (enable) begin
            // Hold operation: Hold data_in in the register when enable is high
            q <= data_in;
        end
    end

endmodule

