module pedestrian_crossing_signal (
  input request,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg [1:0] signal);parameter STOP=0, WALK=1, WAIT=2;

    always_comb begin
        case (state)
            STOP: next_state = request ? WALK : STOP;
            WALK: next_state = WAIT;
            WAIT: next_state = STOP;
        endcase
    end

    always_comb begin
        case (state)
            STOP: signal = 2'b00;
            WALK: signal = 2'b01;
            WAIT: signal = 2'b10;
        endcase
    end

endmodule

