module top_module(
  input                     aclk,
  input [32-1:0]            s_axis_tdata,
  input                     s_axis_tvalid,
  input [8-1:0]             cmd,
  output reg [4-1:0]        cs,
  output reg                sdi,
  output reg                sclk,
  output reg                s_axis_tready
);reg [32-1:0]              data_reg;
  reg [8-1:0]               cmd_reg;
  reg [4-1:0]               cs_reg;
  reg                       sdi_reg;
  reg                       sclk_reg;
  reg                       busy;

  always @(posedge aclk) begin
    if (s_axis_tvalid && !busy) begin
      data_reg <= s_axis_tdata;
      cmd_reg <= cmd;
      cs_reg <= 4'b1110;
      sdi_reg <= 1'b1;
      sclk_reg <= 1'b0;
      s_axis_tready <= 1'b1;
      busy <= 1'b1;
    end else if (busy) begin
      if (cs_reg == 4'b1110) begin
        cs_reg <= 4'b1101;
        sdi_reg <= data_reg[31];
        data_reg <= {data_reg[30:0], 1'b0};
      end else if (cs_reg == 4'b1101) begin
        cs_reg <= 4'b1011;
        sdi_reg <= data_reg[31];
        data_reg <= {data_reg[30:0], 1'b0};
      end else if (cs_reg == 4'b1011) begin
        cs_reg <= 4'b0111;
        sdi_reg <= data_reg[31];
        data_reg <= {data_reg[30:0], 1'b0};
      end else if (cs_reg == 4'b0111) begin
        cs_reg <= 4'b1110;
        sdi_reg <= cmd_reg[7];
        cmd_reg <= {cmd_reg[6:0], 1'b0};
      end else begin
        busy <= 1'b0;
        s_axis_tready <= 1'b0;
      end
      sclk_reg <= ~sclk_reg;
    end else begin
      cs_reg <= 4'b1111;
      sdi_reg <= 1'b0;
      sclk_reg <= 1'b0;
      s_axis_tready <= 1'b0;
    end
  end

  assign cs = cs_reg;
  assign sdi = sdi_reg;
  assign sclk = sclk_reg;

endmodule

