module mux8to1_4bit_active_high (
  input [3:0] in0,
  input [3:0] in1,
  input [3:0] in2,
  input [3:0] in3,
  input [3:0] in4,
  input [3:0] in5,
  input [3:0] in6,
  input [3:0] in7,
  input [2:0] sel,
  input en,
  output reg [3:0] out
);

  always @(*) begin
    if (en) begin
      case (sel)
        3'b000: out = in0;
        3'b001: out = in1;
        3'b010: out = in2;
        3'b011: out = in3;
        3'b100: out = in4;
        3'b101: out = in5;
        3'b110: out = in6;
        3'b111: out = in7;
        default: out = 4'b0000;
      endcase
    end else begin
      out = 4'b0000;
    end
  end

endmodule

