code:
module top_module(
    input clk,
    input srst,
    input we,
    input rd,            // 'rd' should be an input signal to control read operation
    input [7:0] din,
    output reg [7:0] dout // Change dout from wire to reg
);reg [7:0] memory [0:1023];
    reg [9:0] head = 0;
    reg [9:0] tail = 0;
    reg empty = 1;
    reg full = 0;

    always @(posedge clk or negedge srst) begin
        if (!srst) begin
            head <= 0;
            tail <= 0;
            empty <= 1;
            full <= 0;
            dout <= 8'b0;     // Initialize dout on reset
        end else begin
            if (we && !full) begin
                memory[tail] <= din;
                tail <= tail + 1;
                if (tail == 1024) begin
                    tail <= 0;
                end
                empty <= 0;
                if (tail == head) begin
                    full <= 1;
                end
            end
            if (rd && !empty) begin
                dout <= memory[head]; // dout can be assigned as it is now declared as reg
                head <= head + 1;
                if (head == 1024) begin
                    head <= 0;
                end
                full <= 0;
                if (head == tail) begin
                    empty <= 1;
                end
            end else if (empty && rd) begin
                dout <= 8'b0; // Provide a default value for dout when empty
            end
        end
    end

endmodule

