description:
Implement a one-bit full adder. The module takes three one-bit inputs (A, B, and Ci for carry input) and produces two one-bit outputs: S (sum) and Co (carry output). The sum S is calculated by performing an XOR operation on A and B, followed by an XOR with the carry input Ci, while the carry output Co is determined through a combination of logical AND operations and an OR operation, ensuring that the correct carry signal is produced based on the inputs.
module top_module(
         input A, B, Ci,
         output S, Co
       );

code:
module top_module(
         input A, B, Ci,
         output S, Co
       );reg ABsum;
reg ABcarry, Ccarry;

reg S_lcl, Co_lcl;

assign S = S_lcl;
assign Co = Co_lcl;


always @( * ) begin
  ABsum <= #10 A ^ B;
  S_lcl <= #10 Ci ^ ABsum;
end


always @( * ) begin
  Ccarry <= #10 ABsum & Ci;
  ABcarry <= #10 A & B;
  Co_lcl <= #10 Ccarry | ABcarry;
end

endmodule

