module gray_counter_3 
(
  input rst,
  input clk,
  input enable,

  output reg [2:0] gray_count
);

  reg [2:0] count;

  always @(posedge clk or posedge rst) begin
    if (rst) 
	begin
      count <= 3'b000;
      gray_count <= 3'b000;
    end 

	else if (enable) 
	begin
      count <= count + 1;
      gray_count <= count ^ (count >> 1);
    end 

	else begin
      gray_count <= gray_count; // Pause the count when enable is low
    end
  end

endmodule

