module top_module(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty
);input rst;
input wr_clk;
input rd_clk;
input [12 : 0] din;
input wr_en;
input rd_en;
output [12 : 0] dout;
output full;
output empty;

reg [12:0] mem[0:127];
reg [6:0] wr_ptr = 0;
reg [6:0] rd_ptr = 0;
wire [6:0] next_wr_ptr;
wire [6:0] next_rd_ptr;
wire full_flag;
wire empty_flag;

assign next_wr_ptr = (wr_ptr == 127) ? 0 : wr_ptr + 1;
assign next_rd_ptr = (rd_ptr == 127) ? 0 : rd_ptr + 1;
assign full = full_flag;
assign empty = empty_flag;
assign dout = mem[rd_ptr];

always @(posedge wr_clk or negedge rst) begin
  if (!rst) begin
    wr_ptr <= 0;
  end else if (wr_en && !full_flag) begin
    mem[wr_ptr] <= din;
    wr_ptr <= next_wr_ptr;
  end
end

always @(posedge rd_clk or negedge rst) begin
  if (!rst) begin
    rd_ptr <= 0;
  end else if (rd_en && !empty_flag) begin
    rd_ptr <= next_rd_ptr;
  end
end

assign full_flag = (next_wr_ptr == rd_ptr);
assign empty_flag = (wr_ptr == rd_ptr);

endmodule

