		opctr_counting <= opctr_counting;
		opctr <= opctr + 10'd1;
		data_out <= 1'b1;
		end
	else if (opctr == OPWIDTH) begin
		opctr_counting <= 1'b0;
		opctr <= opctr + 10'd1;
		data_out <= 1'b0;
		end
	else begin
		opctr_counting <= opctr_counting;
		opctr <= opctr + 10'd1;
		data_out <= data_out;
		end

end

assign dout_en = dout_en_a & ~dout_en_b;

