module top_module(
  input CLK,
  input EN,
  input TE,
  output reg ENCLK  // Change ENCLK to reg, since it's driven by an always block
);wire AND_out;
  reg D_flipflop_out; // Change D_flipflop_out to reg as it needs to hold state.

  // First stage: AND gate
  assign AND_out = EN & TE;

  // Second stage: D flip-flop
  always @(posedge CLK) begin
    if (EN) begin
      D_flipflop_out <= AND_out;
    end
  end

  // Output
  always @(posedge CLK) begin
    ENCLK <= D_flipflop_out; // Update ENCLK inside an always block
  end

endmodule

