description:
Create a Verilog module for a 3-bit Gray code counter with synchronous active high reset.
// (1) reset: Resets the counter to 3'b000 when high.
// (2) q: The value of the counter.

module gray_counter(
    input clk,
    input reset,
    output reg [2:0] q);

code:
module gray_counter(
    input clk,
    input reset,
    output reg [2:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset
            q <= 3'b000;
        end else begin
            // Gray code counter logic
            q <= q + 1'b1;
            q[2] <= q[2] ^ q[1];
            q[1] <= q[1] ^ q[0];
        end
    end

endmodule

